INSERT INTO ai_playerbot_texts (id, name, text, say_type, reply_type, text_loc1, text_loc2, text_loc3, text_loc4, text_loc5, text_loc6, text_loc7, text_loc8) VALUES
(1830, 'craft_usage', 'Usage: ''craft'', ''craft [item link] [count]'', ''craft ?'' or ''craft reset''', 0, 0, '사용법: ''craft'', ''craft [아이템 링크] [개수]'', ''craft ?'' 또는 ''craft reset''', 'Utilisation : ''craft'', ''craft [lien d''objet] [nombre]'', ''craft ?'' ou ''craft reset''', 'Verwendung: ''craft'', ''craft [Gegenstandslink] [Anzahl]'', ''craft ?'' oder ''craft reset''', '用法：''craft''、''craft [物品链接] [数量]''、''craft ?'' 或 ''craft reset''', '用法：''craft''、''craft [物品連結] [數量]''、''craft ?'' 或 ''craft reset''', 'Uso: ''craft'', ''craft [enlace de objeto] [cantidad]'', ''craft ?'' o ''craft reset''', 'Uso: ''craft'', ''craft [enlace de objeto] [cantidad]'', ''craft ?'' o ''craft reset''', 'Использование: ''craft'', ''craft [ссылка на предмет] [количество]'', ''craft ?'' или ''craft reset'''),
(1930, 'craft_master_only', 'I only take crafting orders from the player I''m with', 0, 0, '제작 주문은 함께하는 플레이어에게서만 받습니다', 'Je n''accepte les commandes d''artisanat que du joueur avec qui je suis', 'Ich nehme Herstellungsaufträge nur von dem Spieler an, mit dem ich unterwegs bin', '我只接受与我同行的玩家的制作订单', '我只接受與我同行的玩家的製作訂單', 'Solo acepto encargos de fabricación del jugador con el que estoy', 'Solo acepto encargos de fabricación del jugador con el que estoy', 'Я принимаю заказы на изготовление только от игрока, с которым я нахожусь'),
(1931, 'craft_busy', 'I''m already working on an order for %item. Say ''craft reset'' to cancel it first', 0, 0, '이미 %item 주문을 처리하고 있습니다. 먼저 ''craft reset''으로 취소하세요', 'Je travaille déjà sur une commande de %item. Dites ''craft reset'' pour l''annuler d''abord', 'Ich arbeite bereits an einem Auftrag für %item. Sag zuerst ''craft reset'', um ihn abzubrechen', '我已经在处理 %item 的订单。请先输入 ''craft reset'' 取消它', '我已經在處理 %item 的訂單。請先輸入 ''craft reset'' 取消它', 'Ya estoy trabajando en un encargo de %item. Di ''craft reset'' para cancelarlo primero', 'Ya estoy trabajando en un encargo de %item. Di ''craft reset'' para cancelarlo primero', 'Я уже выполняю заказ на %item. Сначала скажите ''craft reset'', чтобы отменить его'),
(1932, 'craft_bind_on_pickup', 'I can''t craft %item for you: it is bind on pickup, so I couldn''t trade it to you', 0, 0, '%item은(는) 획득 시 귀속 아이템이라 거래해 드릴 수 없으므로 제작해 드릴 수 없습니다', 'Je ne peux pas fabriquer %item pour vous : il est lié quand ramassé, je ne pourrais donc pas vous l''échanger', 'Ich kann %item nicht für dich herstellen: Es wird beim Aufheben gebunden, also könnte ich es dir nicht geben', '我无法为你制作 %item：它是拾取后绑定的，我无法交易给你', '我無法為你製作 %item：它是拾取後綁定的，我無法交易給你', 'No puedo fabricar %item para ti: se liga al recogerlo, así que no podría comerciártelo', 'No puedo fabricar %item para ti: se liga al recogerlo, así que no podría comerciártelo', 'Я не могу изготовить для вас %item: он становится персональным при получении, и я не смогу передать его вам'),
(1933, 'craft_needs_station', 'This recipe needs me to stand next to a crafting station, such as an anvil, forge or cooking fire', 0, 0, '이 제조법은 모루, 용광로, 요리용 불 같은 제작대 옆에 있어야 합니다', 'Cette recette exige que je me tienne près d''un poste d''artisanat, comme une enclume, une forge ou un feu de cuisine', 'Für dieses Rezept muss ich neben einer Werkstation stehen, etwa einem Amboss, einer Schmiede oder einem Kochfeuer', '这个配方需要我站在制作台旁边，例如铁砧、熔炉或烹饪火堆', '這個配方需要我站在製作台旁邊，例如鐵砧、熔爐或烹飪火堆', 'Esta receta requiere que esté junto a una estación de fabricación, como un yunque, una forja o un fuego de cocina', 'Esta receta requiere que esté junto a una estación de fabricación, como un yunque, una forja o un fuego de cocina', 'Для этого рецепта мне нужно стоять рядом с ремесленным оборудованием, например наковальней, горном или костром'),
(1934, 'craft_progress', 'Crafted %crafted of %count', 0, 0, '%count개 중 %crafted개 제작함', '%crafted sur %count fabriqués', '%crafted von %count hergestellt', '已制作 %crafted / %count', '已製作 %crafted / %count', 'Fabricados %crafted de %count', 'Fabricados %crafted de %count', 'Изготовлено %crafted из %count'),
(1935, 'craft_done', 'I''ve crafted %item. Open a trade with me to collect it', 0, 0, '%item을(를) 제작했습니다. 저와 거래를 열어 받아 가세요', 'J''ai fabriqué %item. Ouvrez un échange avec moi pour le récupérer', 'Ich habe %item hergestellt. Öffne einen Handel mit mir, um es abzuholen', '我已制作好 %item。与我交易即可领取', '我已製作好 %item。與我交易即可領取', 'He fabricado %item. Abre un comercio conmigo para recogerlo', 'He fabricado %item. Abre un comercio conmigo para recogerlo', 'Я изготовил %item. Откройте со мной обмен, чтобы забрать'),
(1936, 'craft_refund_mailed', 'I''ve mailed you back what''s left of your order for %item', 0, 0, '%item 주문에서 남은 것을 우편으로 돌려보냈습니다', 'Je vous ai renvoyé par courrier ce qui reste de votre commande de %item', 'Ich habe dir zurückgeschickt, was von deinem Auftrag für %item übrig ist', '我已将你 %item 订单的剩余物品邮寄给你', '我已將你 %item 訂單的剩餘物品郵寄給你', 'Te he devuelto por correo lo que queda de tu encargo de %item', 'Te he devuelto por correo lo que queda de tu encargo de %item', 'Я отправил вам почтой то, что осталось от вашего заказа на %item'),
(1937, 'craft_refund_mail_subject', 'Your crafting order', 0, 0, '제작 주문', 'Votre commande d''artisanat', 'Dein Herstellungsauftrag', '你的制作订单', '你的製作訂單', 'Tu encargo de fabricación', 'Tu encargo de fabricación', 'Ваш заказ на изготовление'),
(1938, 'craft_reagent_bind_on_pickup', 'I can''t take an order for %item: %reagent is bind on pickup, so you couldn''t trade it to me', 0, 0, '%item 주문은 받을 수 없습니다: %reagent은(는) 획득 시 귀속이라 저에게 거래할 수 없습니다', 'Je ne peux pas accepter de commande de %item : %reagent est lié quand ramassé, vous ne pourriez donc pas me l''échanger', 'Ich kann keinen Auftrag für %item annehmen: %reagent wird beim Aufheben gebunden, du könntest es mir also nicht geben', '我无法接受 %item 的订单：%reagent 是拾取后绑定的，你无法交易给我', '我無法接受 %item 的訂單：%reagent 是拾取後綁定的，你無法交易給我', 'No puedo aceptar un encargo de %item: %reagent se liga al recogerlo, así que no podrías comerciármelo', 'No puedo aceptar un encargo de %item: %reagent se liga al recogerlo, así que no podrías comerciármelo', 'Я не могу принять заказ на %item: %reagent становится персональным при получении, и вы не сможете передать его мне'),
(1939, 'craft_missing_tool', 'I don''t have the tool needed to craft %item', 0, 0, '%item을(를) 제작하는 데 필요한 도구가 없습니다', 'Je n''ai pas l''outil nécessaire pour fabriquer %item', 'Mir fehlt das Werkzeug, um %item herzustellen', '我没有制作 %item 所需的工具', '我沒有製作 %item 所需的工具', 'No tengo la herramienta necesaria para fabricar %item', 'No tengo la herramienta necesaria para fabricar %item', 'У меня нет инструмента, нужного для изготовления %item'),
(1940, 'craft_on_cooldown', 'I can''t craft %item again until its cooldown ends', 0, 0, '재사용 대기시간이 끝날 때까지 %item을(를) 다시 제작할 수 없습니다', 'Je ne peux pas refabriquer %item avant la fin de son temps de recharge', 'Ich kann %item erst wieder herstellen, wenn die Abklingzeit vorbei ist', '在冷却结束前我无法再次制作 %item', '在冷卻結束前我無法再次製作 %item', 'No puedo volver a fabricar %item hasta que termine su tiempo de reutilización', 'No puedo volver a fabricar %item hasta que termine su tiempo de reutilización', 'Я не могу снова изготовить %item, пока не пройдёт время восстановления'),
(1941, 'craft_unique_held', 'I already have as many %item as I can hold', 0, 0, '%item은(는) 이미 가질 수 있는 만큼 가지고 있습니다', 'J''ai déjà autant de %item que je peux en porter', 'Ich habe bereits so viele %item, wie ich tragen kann', '我身上的 %item 已达到上限', '我身上的 %item 已達到上限', 'Ya tengo tantos %item como puedo llevar', 'Ya tengo tantos %item como puedo llevar', 'У меня уже столько %item, сколько я могу носить'),
(1942, 'craft_limit_one', 'I can only craft one %item at a time', 0, 0, '%item은(는) 한 번에 하나만 제작할 수 있습니다', 'Je ne peux fabriquer qu''un seul %item à la fois', 'Ich kann immer nur ein %item auf einmal herstellen', '我一次只能制作一个 %item', '我一次只能製作一個 %item', 'Solo puedo fabricar un %item a la vez', 'Solo puedo fabricar un %item a la vez', 'Я могу изготовить только один %item за раз'),
(1943, 'craft_item_reserved', '%item is reserved for a crafting order', 0, 0, '%item은(는) 제작 주문용으로 보관 중입니다', '%item est réservé pour une commande d''artisanat', '%item ist für einen Herstellungsauftrag reserviert', '%item 已为制作订单保留', '%item 已為製作訂單保留', '%item está reservado para un encargo de fabricación', '%item está reservado para un encargo de fabricación', '%item зарезервирован для заказа на изготовление'),
(1944, 'craft_collect_limit', 'I can only hand over %count of %item', 0, 0, '%item은(는) %count개만 건네줄 수 있습니다', 'Je ne peux remettre que %count %item', 'Ich kann nur %count %item übergeben', '我只能交给你 %count 个 %item', '我只能交給你 %count 個 %item', 'Solo puedo entregarte %count de %item', 'Solo puedo entregarte %count de %item', 'Я могу передать только %count шт. %item'),
(1945, 'craft_no_bag_space', 'I don''t have enough bag space to craft %item', 0, 0, '%item을(를) 제작할 가방 공간이 부족합니다', 'Je n''ai pas assez de place dans mes sacs pour fabriquer %item', 'Ich habe nicht genug Taschenplatz, um %item herzustellen', '我的背包空间不足，无法制作 %item', '我的背包空間不足，無法製作 %item', 'No tengo suficiente espacio en las bolsas para fabricar %item', 'No tengo suficiente espacio en las bolsas para fabricar %item', 'У меня недостаточно места в сумках, чтобы изготовить %item'),
(1946, 'craft_bag_space_limit', 'I only have bag space to craft %count %item', 0, 0, '가방 공간이 부족해 %item은(는) %count개만 제작할 수 있습니다', 'Je n''ai de place dans mes sacs que pour fabriquer %count %item', 'Ich habe nur Taschenplatz, um %count %item herzustellen', '我的背包空间只够制作 %count 个 %item', '我的背包空間只夠製作 %count 個 %item', 'Solo tengo espacio en las bolsas para fabricar %count de %item', 'Solo tengo espacio en las bolsas para fabricar %count de %item', 'Места в сумках хватит только на %count шт. %item');

